(()=>{'use strict';const {armorTier,structureLabel,NetworkView}=FrontlinePresentation,networkView=new NetworkView();let lastUI=0;const {B,Game,W,H,LEVELS,OPTIONS,WEAPONS,ROUTES,DIRT_ROADS,surfaceAt,factionName,factionColors,tankPivot,distance}=Frontline,$=id=>document.getElementById(id),canvas=$('field'),ctx=canvas.getContext('2d');let game=new Game(),view=game.snapshot(0),network=false,team=0,token=null,stream=null,rangeVisible=true,last=performance.now(),lastMessage='',connecting=false,closed=false,serverAvailable=false,roundTrip=0,overview=false,camera={x:0,y:0,zoom:1};const VW=canvas.width,VH=canvas.height,fogCanvas=document.createElement('canvas');fogCanvas.width=VW;fogCanvas.height=VH;const fog=fogCanvas.getContext('2d');
function send(cmd){if(network){fetch('/api/command',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(cmd)}).then(r=>{if(!r.ok)throw Error('Команда не доставлена');}).catch(e=>$('netStatus').textContent=e.message);}else game.command(team,cmd);}
function circle(x,y,r,color){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(color){ctx.fillStyle=color;ctx.fill();}else ctx.stroke();}
function drawRepair(u,s){const r=u.repairVisual;if(!r||r.cancelAt!==null||u.stunnedUntil>s.time)return;const progress=Math.max(0,Math.min(1,(s.time-r.started)/(r.warmup||5)));ctx.save();if(progress<1){ctx.lineWidth=4;ctx.strokeStyle='#c5d7ce55';circle(u.x,u.y,u.r+11);ctx.strokeStyle='#bde6aa';ctx.beginPath();ctx.arc(u.x,u.y,u.r+11,-Math.PI/2,-Math.PI/2+Math.PI*2*progress);ctx.stroke();}else{ctx.font='22px "Segoe UI Emoji",sans-serif';ctx.textAlign='center';ctx.fillText('🔧',u.x,u.y-u.r-35);}ctx.restore();}
function color(faction){return factionColors(faction,team,network).main;}
function hp(u,w=32){ctx.fillStyle='#111c18';ctx.fillRect(u.x-w/2,u.y-u.r-10,w,4);ctx.fillStyle=color(u.team);ctx.fillRect(u.x-w/2,u.y-u.r-10,w*Math.max(0,u.hp/u.max),4);}
function draw(){const s=view;if(!s)return;camera.zoom=overview?VW/W:1;camera.x=overview?0:Math.max(0,Math.min(W-VW,s.me.tank.x-VW/2));camera.y=overview?0:Math.max(0,Math.min(H-VH,s.me.tank.y-VH/2));ctx.save();ctx.scale(camera.zoom,camera.zoom);ctx.translate(-camera.x,-camera.y);ctx.fillStyle='#222f26';ctx.fillRect(0,0,W,H);ctx.lineWidth=1;ctx.strokeStyle='#2d3b2f';for(let x=0;x<W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}for(let y=0;y<H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
ctx.lineCap='round';ctx.strokeStyle='#735d43';ctx.lineWidth=64;for(const road of DIRT_ROADS){ctx.beginPath();ctx.moveTo(road[0].x,road[0].y);ctx.lineTo(road[1].x,road[1].y);ctx.stroke();}circle(1200,700,135,'#735d43');for(const route of ROUTES){ctx.lineWidth=68;ctx.lineJoin='round';ctx.strokeStyle='#55545a';ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.lineWidth=1;ctx.strokeStyle='#aaa5a0';ctx.setLineDash([13,18]);ctx.stroke();ctx.setLineDash([]);}ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillStyle='#c3c8b4';ctx.fillText('ВЕРХНЯЯ ЛИНИЯ',1200,100);ctx.fillText('НИЖНЯЯ ЛИНИЯ',1200,1300);
ctx.strokeStyle='#c7bd8c88';ctx.lineWidth=1;ctx.setLineDash([4,7]);circle(s.point.x,s.point.y,95);ctx.setLineDash([]);const active=s.entities.find(u=>u.kind==='turret');ctx.fillStyle='#d4d7bd';ctx.fillText(active?(active.team===-1?'ТУРЕЛЬ FIA':'КОНТРОЛЬ: '+factionName(active.team)):s.point.respawnAt?'FIA ЧЕРЕЗ '+Math.ceil(Math.max(0,s.point.respawnAt-s.time))+' с':'ЗАХВАТ '+Math.round(s.point.progress/(s.balance||B).structures.central.captureSeconds*100)+'%',s.point.x,s.point.y+115);
for(const c of s.covers||[]){ctx.fillStyle='#7b8079';circle(c.x,c.y,c.r,ctx.fillStyle);ctx.strokeStyle='#b4b7a6';circle(c.x,c.y,c.r);ctx.fillStyle='#555d57';ctx.fillRect(c.x-c.r*.6,c.y-4,c.r*1.2,8);}drawFog(s);if(!active&&s.point.respawnAt){const left=Math.ceil(Math.max(0,s.point.respawnAt-s.time));ctx.fillStyle='#e4ca9b';ctx.fillText('FIA ЧЕРЕЗ '+Math.floor(left/60)+':'+String(left%60).padStart(2,'0'),s.point.x,s.point.y+115);}if(active){ctx.strokeStyle='#d5ab7088';ctx.setLineDash([10,8]);circle(active.x,active.y,active.range);ctx.setLineDash([]);ctx.fillStyle='#e4ca9b';ctx.fillText('ДАЛЬНОСТЬ '+active.range,active.x,active.y-active.range-10);}for(const u of s.ruins){ctx.strokeStyle='#807b6b';ctx.beginPath();ctx.moveTo(u.x-12,u.y-12);ctx.lineTo(u.x+12,u.y+12);ctx.moveTo(u.x+12,u.y-12);ctx.lineTo(u.x-12,u.y+12);ctx.stroke();}
const me=s.me,tank=me.tank;if(rangeVisible&&tank.hp>0){ctx.strokeStyle='#8ebacc44';circle(tank.x,tank.y,tank.vision);ctx.strokeStyle='#c5d28b77';ctx.setLineDash([4,7]);circle(tank.x,tank.y,tank.range);ctx.setLineDash([]);}
if(me.order&&tank.hp>0){const target=me.order.type==='move'?me.order:s.entities.find(u=>u.id===me.order.id);if(target){ctx.strokeStyle=me.order.type==='move'?(me.order.reverse?'#a0c9e4':'#c9dc95'):'#eb9177';ctx.setLineDash([4,7]);ctx.beginPath();ctx.moveTo(tank.x,tank.y);ctx.lineTo(target.x,target.y);ctx.stroke();ctx.setLineDash([]);if(me.order.type==='attack')ctx.strokeRect(target.x-target.r-4,target.y-target.r-4,target.r*2+8,target.r*2+8);}}
for(const u of s.entities){if(u.kind==='infantry'){circle(u.x,u.y,10,'#122019');if(u.role==='HAT'){ctx.fillStyle=color(u.team);ctx.beginPath();ctx.moveTo(u.x,u.y-10);ctx.lineTo(u.x+10,u.y);ctx.lineTo(u.x,u.y+10);ctx.lineTo(u.x-10,u.y);ctx.closePath();ctx.fill();}else if(u.role==='sniper'){ctx.fillStyle=color(u.team);ctx.beginPath();ctx.moveTo(u.x,u.y-9);ctx.lineTo(u.x+8,u.y+7);ctx.lineTo(u.x-8,u.y+7);ctx.fill();}else circle(u.x,u.y,7,color(u.team));ctx.strokeStyle=color(u.team);ctx.lineWidth=u.role==='HAT'?4:2;ctx.beginPath();ctx.moveTo(u.x,u.y);ctx.lineTo(u.x+(u.team?-13:13),u.y);ctx.stroke();ctx.lineWidth=1;if(u.role!=='rifle'){ctx.fillStyle='#e5e7cf';ctx.font='10px system-ui';ctx.fillText(u.role==='sniper'?'S':u.role,u.x,u.y+22);ctx.font='12px system-ui';}hp(u,22);}else if(u.kind==='tank'){const palette=factionColors(u.team,team,network);drawRepair(u,s);ctx.save();ctx.translate(u.x,u.y);ctx.rotate(u.angle);ctx.fillStyle='#101a14';ctx.fillRect(-24,-19,48,10);ctx.fillRect(-24,9,48,10);ctx.fillStyle=network?palette.main:'#b8ca80';ctx.fillRect(-21,-13,42,26);ctx.strokeStyle=network?palette.outline:'#e2eeb4';ctx.strokeRect(-21,-13,42,26);ctx.fillStyle=network?palette.front:'#dae4ba';ctx.fillRect(16,-10,4,20);ctx.fillStyle=network?palette.rear:'#41523a';ctx.fillRect(-19,-8,5,16);ctx.restore();ctx.save();const pivot=tankPivot(u);ctx.translate(pivot.x,pivot.y);ctx.rotate(u.turret);ctx.fillStyle=palette.barrel;ctx.fillRect(0,-2.5,35,5);circle(0,0,11,palette.turret);ctx.restore();hp(u,55);ctx.fillStyle='#e2e9d0';ctx.fillText(armorTier(u.armor),u.x,u.y-48);if(u.id===tank.id&&(me.repair||me.stunnedUntil>s.time)){ctx.fillStyle=me.stunnedUntil>s.time?'#edac7b':'#bce6c0';ctx.fillText(me.stunnedUntil>s.time?'СТАН '+(me.stunnedUntil-s.time).toFixed(1):me.repair.cancelAt!==null?'ОТМЕНА РЕМОНТА':s.time-me.repair.started<me.repairWarmup?'ПОДГОТОВКА РЕМОНТА':'РЕМОНТ +'+me.repairRate+' HP/с',u.x,u.y+45);}}else{ctx.fillStyle=factionColors(u.team,team,network).fill;ctx.strokeStyle=color(u.team);if(u.kind==='base'){ctx.fillRect(u.x-26,u.y-26,52,52);ctx.strokeRect(u.x-26,u.y-26,52,52);for(const gun of u.guns||[]){ctx.save();ctx.translate(u.x,u.y+gun.offset);ctx.rotate(gun.angle);ctx.fillStyle=color(u.team);ctx.fillRect(0,-3,38,6);circle(0,0,7,color(u.team));ctx.restore();}}else{circle(u.x,u.y,u.r,ctx.fillStyle);circle(u.x,u.y,u.r);ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(u.x,u.y);ctx.lineTo(u.x+Math.cos(u.turret||0)*30,u.y+Math.sin(u.turret||0)*30);ctx.stroke();ctx.lineWidth=1;}hp(u,52);ctx.fillStyle='#e1e8d0';ctx.fillText(structureLabel(u,factionName),u.x,u.y+u.r+17);}}
for(const e of s.effects){ctx.globalAlpha=e.life/.4*.5;circle(e.x,e.y,e.r,e.kind==='HE'?'#ffb16a':e.kind==='capture'?'#a3d48c':'#d8bc82');}ctx.globalAlpha=1;for(const f of s.smokes){const d=f.density*Math.min(f.age/2,1);ctx.globalAlpha=Math.max(.06,Math.min(.85,d/3));circle(f.x,f.y,f.r,'#9ca6a8');ctx.globalAlpha=1;ctx.fillStyle='#e2e8dc';ctx.fillText(d>=(f.threshold??1.2)?'ПЛОТНЫЙ ДЫМ':Math.round(d/(f.threshold??1.2)*100)+'%',f.x,f.y);}for(const b of s.shots)circle(b.x,b.y,b.r,b.kind==='AP'?'#ffe5a0':b.kind==='HE'?'#ffbb78':color(b.team));ctx.restore();drawMinimap(s);if(tank.hp<=0){ctx.fillStyle='#e1cc8c';ctx.font='20px system-ui';ctx.fillText('ВОЗРОЖДЕНИЕ '+Math.ceil(me.respawn),VW/2,VH-50);}if(s.over||s.paused){ctx.fillStyle='#101a14c9';ctx.fillRect(0,0,VW,VH);ctx.fillStyle='#e1e8dc';ctx.font='28px system-ui';ctx.textAlign='center';ctx.fillText(s.over?(s.over.winner===team?'ПОБЕДА':'ПОРАЖЕНИЕ'):'ПАУЗА',VW/2,VH/2);ctx.font='14px system-ui';if(s.over)ctx.fillText('База уничтожена · «Заново» для нового матча',VW/2,VH/2+30);}}
function drawFog(s){fog.setTransform(1,0,0,1,0,0);fog.globalCompositeOperation='source-over';fog.clearRect(0,0,VW,VH);fog.fillStyle='rgba(6,12,13,.68)';fog.fillRect(0,0,VW,VH);fog.globalCompositeOperation='destination-out';fog.save();fog.scale(camera.zoom,camera.zoom);fog.translate(-camera.x,-camera.y);for(const u of s.vision||[]){fog.beginPath();const dense=s.smokes.filter(f=>f.density*Math.min(f.age/2,1)>=(f.threshold??1.2));for(let i=0;i<=72;i++){const angle=i/72*Math.PI*2,dx=Math.cos(angle),dy=Math.sin(angle);let ray=u.vision;for(const f of [...dense,...(s.covers||[])]){const ox=u.x-f.x,oy=u.y-f.y,C=ox*ox+oy*oy-f.r*f.r;if(C<=0){ray=Math.min(ray,u.r+5);continue;}const B=ox*dx+oy*dy,disc=B*B-C;if(disc>=0){const t=-B-Math.sqrt(disc);if(t>=0)ray=Math.min(ray,t);}}const x=u.x+dx*ray,y=u.y+dy*ray;if(i===0)fog.moveTo(x,y);else fog.lineTo(x,y);}fog.closePath();fog.fill();}fog.restore();fog.globalCompositeOperation='source-over';ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(fogCanvas,0,0);ctx.restore();}
function drawMinimap(s){const w=216,h=126,x=VW-w-12,y=12,scale=w/W;ctx.save();ctx.fillStyle='#15201fe8';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#8d9b91';ctx.strokeRect(x,y,w,h);ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.strokeStyle='#735d43';ctx.lineWidth=40;for(const road of DIRT_ROADS){ctx.beginPath();ctx.moveTo(road[0].x,road[0].y);ctx.lineTo(road[1].x,road[1].y);ctx.stroke();}ctx.strokeStyle='#74756c';ctx.lineWidth=35;for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}for(const e of s.entities){circle(e.x,e.y,e.kind==='tank'?36:e.kind==='infantry'?13:23,color(e.team));}ctx.strokeStyle='#e2e8dc';ctx.lineWidth=8;ctx.strokeRect(camera.x,camera.y,VW/camera.zoom,VH/camera.zoom);ctx.restore();ctx.font='12px system-ui';ctx.fillStyle='#d5decd';ctx.textAlign='right';ctx.fillText('M — общий вид · Y — сменить сторону',x+w,y+h+17);ctx.restore();}
function switchSide(){if(network){$('netStatus').textContent='Переключение Y доступно в одиночной демке.';return;}game.command(team,{type:'smoke',held:false});team=1-team;view=game.snapshot(team);$('mode').textContent='Тренировка · '+factionName(team);}

function ui(){const s=view,p=s.me,c=p.cannon;$('hp').textContent=Math.ceil(p.tank.hp)+' / '+p.tank.max;$('wave').textContent='Волна '+s.wave+' · '+Math.ceil(Math.max(0,s.nextWave-s.time))+' с';$('kills').textContent=p.kills;const bases=[...s.entities,...s.ruins].filter(e=>e.kind==='base');$('basehp').textContent=bases.map(e=>factionName(e.team)+': '+Math.ceil(e.hp)).join(' · ');$('level').textContent='УРОВЕНЬ '+p.level+' / '+OPTIONS.length;$('xpbar').max=LEVELS[p.level]||LEVELS[LEVELS.length-1];$('xpbar').value=p.xp;$('xp').textContent=Math.floor(p.xp)+(p.level<OPTIONS.length?' / '+LEVELS[p.level]:' · МАКС');$('stats').textContent='Броня '+armorTier(p.tank.armor)+' · дальность '+Math.round(p.tank.range)+' · обзор '+Math.round(p.tank.vision);$('ammoText').textContent=c.loaded?'Заряжен: '+c.loaded:'Зарядка '+c.target+' · '+(c.left/p.attackSpeed).toFixed(1)+' с';$('reloadbar').value=c.loaded?1:1-c.left/(c.total||1);$('shellIcon').textContent=c.loaded==='AP'?'▰':c.loaded==='HE'?'◆':'◇';for(const n of Object.keys(WEAPONS))$('weapon'+n).setAttribute('aria-pressed',String(n===p.weapon));$('weaponInfo').textContent=(p.switchLeft>0?'Переключение '+p.switchLeft.toFixed(1)+' с · ':'')+(p.weapon==='Smoke'?'Удерживайте 4 или Smoke.':p.weapon==='HE'?'HE: '+Number(((s.balance||B).weapons.HE.damage*p.heBonus).toFixed(1))+' урона · радиус '+(s.balance||B).projectiles.heRadius:p.weapon==='AP'?'AP: '+Number(((s.balance||B).weapons.AP.damage*p.apBonus).toFixed(1))+' урона':'MG: '+(s.balance||B).weapons.MG.damage+' урона · '+(s.balance||B).weapons.MG.interval+' с');$('smokeFuel').textContent='Бак дыма: '+Math.floor(p.smokeFuel)+'%';$('smokebar').max=(s.balance||B).smoke.capacity;$('smokebar').value=p.smokeFuel;$('combatMode').textContent=(p.fireOnMove&&p.autoAttack?'Автоатака · S — отменить · ':'')+'Задний ход '+Math.round(p.tank.reverseFactor*100)+'%';$('choices').hidden=!p.pending.length||!!s.over;if(p.pending.length){const l=p.pending[0];$('choiceTitle').textContent='Уровень '+l+' · в очереди '+p.pending.length;for(let i=0;i<2;i++)$('choice'+i).textContent=OPTIONS[l-1][i];}$('build').textContent=p.chosen.map(c=>'Ур. '+c.level+': '+OPTIONS[c.level-1][c.choice]).join(' · ');$('state').textContent=p.message;const terrain=surfaceAt(p.tank),repair=p.repair,stun=Math.max(0,p.stunnedUntil-s.time),quiet=Math.max(0,(s.balance||B).recovery.passiveDelay-(s.time-p.lastDamageAt));$('recovery').textContent=stun>0?'Оглушение: '+stun.toFixed(1)+' с':repair?(repair.cancelAt!==null?'Отмена ремонта: '+Math.max(0,repair.cancelAt-s.time).toFixed(1)+' с':s.time-repair.started<p.repairWarmup?'Ремонт: подготовка '+Math.max(0,p.repairWarmup-s.time+repair.started).toFixed(1)+' с':'Активный ремонт: +'+p.repairRate+' HP/с'):(quiet>0?'Пассивная регенерация через '+quiet.toFixed(1)+' с':'Пассивная регенерация: +'+(s.balance||B).recovery.passiveHP+' HP/с');$('terrain').textContent=terrain.name+' · скорость '+Math.round(terrain.factor*100)+'%';$('repair').textContent=repair?'5 · Отменить ремонт':'5 · Активный ремонт';$('repair').setAttribute('aria-pressed',String(!!repair));$('repair').disabled=p.tank.hp<=0||!!s.over||stun>0;$('pause').disabled=network;$('switchSide').disabled=network;$('reset').disabled=network&&team!==0;}
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==2&&e.pointerType!=='touch')return;e.preventDefault();if(!view||view.over)return;const b=canvas.getBoundingClientRect(),pos={x:camera.x+(e.clientX-b.left)*VW/b.width/camera.zoom,y:camera.y+(e.clientY-b.top)*VH/b.height/camera.zoom};const reverse=e.button===0&&e.pointerType!=='touch';if(reverse){send({type:'move',reverse:true,...pos});return;}const target=view.entities.filter(u=>u.id!==view.me.tank.id&&(u.team!==team||e.altKey)&&distance(u,pos)<=u.r+10).sort((a,b)=>distance(a,pos)-distance(b,pos))[0];send(target?{type:'attack',id:target.id}:{type:'move',...pos});});
$('repair').onclick=()=>send({type:'repair'});for(const name of ['AP','HE','MG'])$('weapon'+name).onclick=()=>send({type:'weapon',name});for(let choice=0;choice<2;choice++)$('choice'+choice).onclick=()=>send({type:'upgrade',choice});const smokeButton=$('weaponSmoke');smokeButton.onpointerdown=e=>{e.preventDefault();smokeButton.setPointerCapture(e.pointerId);send({type:'smoke',held:true});};smokeButton.onpointerup=()=>send({type:'smoke',held:false});smokeButton.onpointercancel=()=>send({type:'smoke',held:false});smokeButton.onkeydown=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();if(!e.repeat)send({type:'smoke',held:true});}};smokeButton.onkeyup=()=>send({type:'smoke',held:false});window.addEventListener('blur',()=>send({type:'smoke',held:false}));window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Digit5'){e.preventDefault();if(!e.repeat)send({type:'repair'});return;}if(e.code==='Digit4'){e.preventDefault();if(!e.repeat)send({type:'smoke',held:true});return;}if(e.repeat)return;const name={Digit1:'AP',Digit2:'HE',Digit3:'MG'}[e.code];if(name)send({type:'weapon',name});if(e.code==='KeyY')switchSide();if(e.code==='KeyM')overview=!overview;if(e.code==='KeyS')send({type:'stop'});if(e.code==='KeyR')rangeVisible=!rangeVisible;if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();if(!network)game.paused=!game.paused;}});window.addEventListener('keyup',e=>{if(e.code==='Digit4')send({type:'smoke',held:false});});$('switchSide').onclick=switchSide;$('overview').onclick=()=>overview=!overview;$('pause').onclick=()=>{if(!network)game.paused=!game.paused;};$('reset').onclick=()=>{if(network)send({type:'reset'});else{game=new Game();team=0;$('mode').textContent='Тренировка · NATO';}};
$('online').onclick=async()=>{if(network)return;try{const r=await fetch('/api/info',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();if(!data.frontlineServer)throw Error();serverAvailable=true;$('downloadServer').hidden=true;$('joinForm').hidden=false;$('netStatus').textContent='Введите код из окна сервера. Первый вход — NATO, второй — Soviet.';$('code').focus();}catch{$('netStatus').textContent='Для 1v1 скачайте сервер для Radmin, распакуйте и запустите START-SERVER.cmd. На этой странице работает одиночная версия.';}};
$('join').onclick=async()=>{if(connecting)return;connecting=true;try{const r=await fetch('/api/join',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:$('code').value.trim(),token:sessionStorage.getItem('frontline-seat')||null})}),data=await r.json();if(!r.ok)throw Error(data.error||'Не удалось подключиться');network=true;token=data.token;team=data.team;sessionStorage.setItem('frontline-seat',token);view=data.state;networkView.reset(data.state,performance.now());stream?.close();stream=new EventSource('/api/events?token='+encodeURIComponent(token));stream.onmessage=e=>{const packet=JSON.parse(e.data);networkView.push(packet.state,performance.now());view=networkView.latest;$('netStatus').textContent=packet.connected===2?'Оба игрока подключены · матч идёт':packet.started?'Соединение игрока потеряно · матч приостановлен':'Ожидаем второго игрока…';};stream.onerror=()=>{$('netStatus').textContent='Связь с сервером потеряна. Переподключение…';send({type:'smoke',held:false});};$('mode').textContent='Сетевой матч · '+factionName(team);$('joinForm').hidden=true;$('online').disabled=true;$('netStatus').textContent='Подключение…';}catch(e){$('netStatus').textContent=e.message;}finally{connecting=false;}};
function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!network){game.tick(dt);view=game.snapshot(team);}else view=networkView.sample(now)||view;draw();if(now-lastUI>=100){ui();lastUI=now;}requestAnimationFrame(loop);}requestAnimationFrame(loop);
})();

